Algorithm per requirements:
If Reset AND NOT Fault:
 Alarm := FALSE;
 Acknowledged := FALSE;
ElsIf Fault:
 Alarm := TRUE;
 if Fault AND NOT previous_fault then Acknowledged := FALSE;
 elsif Ack then Acknowledged := TRUE; end_if
Else:
 retain Alarm;
 if Alarm AND Ack then Acknowledged := TRUE; end_if
End_if
Horn := Alarm AND NOT Acknowledged;
previous_fault := Fault;

